def render_page(body_template, msg=None, show_splash=False, **context):
    body = render_template_string(body_template, **context)
    return render_template_string(
        BASE_HTML,
        body=body,
        email=session.get("email"),
        msg=msg,
        show_splash=show_splash,
    )


def base_url():
    configured_url = (
        os.environ.get("PUBLIC_BASE_URL")
        or os.environ.get("RENDER_EXTERNAL_URL")
        or request.host_url
    )
    return configured_url.rstrip("/")


def callback_url():
    return base_url() + "/callback"


def client_config():
    raw = os.environ.get("GOOGLE_CREDENTIALS_JSON", "").strip()

    if raw:
        try:
            return json.loads(raw)
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "GOOGLE_CREDENTIALS_JSON valid JSON nahi hai. "
                "credentials.json ka full content paste karo."
            ) from exc

    if os.path.exists("credentials.json"):
        with open("credentials.json", "r", encoding="utf-8") as file:
            return json.load(file)

    raise RuntimeError(
        "GOOGLE_CREDENTIALS_JSON missing hai. Render Environment me credentials.json ka full content paste karo."
    )


def allowed_emails():
    raw = os.environ.get("ALLOWED_EMAILS", "").strip().lower()
    if not raw:
        return []
    return [item.strip() for item in raw.split(",") if item.strip()]


def credentials_to_dict(credentials):
    return {
        "token": credentials.token,
        "refresh_token": credentials.refresh_token,
        "token_uri": credentials.token_uri,
        "client_id": credentials.client_id,
        "client_secret": credentials.client_secret,
        "scopes": credentials.scopes,
    }


def credentials_from_info(info):
    credentials = Credentials.from_authorized_user_info(info, SCOPES)

    if credentials.expired and credentials.refresh_token:
        credentials.refresh(Request())

    return credentials


def credentials_from_session():
    info = session.get("credentials")
    if not info:
        raise RuntimeError("Login required")

    credentials = credentials_from_info(info)
    session["credentials"] = credentials_to_dict(credentials)
    return credentials


def gmail_service():
    return build("gmail", "v1", credentials=credentials_from_session(), cache_discovery=False)


def gmail_service_from_info(info):
    return build("gmail", "v1", credentials=credentials_from_info(info), cache_discovery=False)


def login_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        if "credentials" not in session:
            return redirect(url_for("home"))
        return fn(*args, **kwargs)

    return wrapper


def make_query(form):
    parts = []
    labels = []

    for key in form.getlist("category"):
        if key in CATEGORIES:
            labels.append(CATEGORIES[key]["label"])
            parts.append("(" + CATEGORIES[key]["query"] + ")")

    custom_query = form.get("custom", "").strip()
    if custom_query:
        labels.append("Custom")
        parts.append("(" + custom_query + ")")

    if not parts:
        raise ValueError("Kam se kam ek category ya custom query select karo.")

    query = " OR ".join(parts)
    date_mode = form.get("date_mode", "all")

    if date_mode == "last":
        days = form.get("days", "").strip()
        if not days.isdigit() or int(days) < 1:
            raise ValueError("Last N days me valid number daalo.")
        query = "(" + query + ") newer_than:" + str(int(days)) + "d"

    elif date_mode == "range":
        after_date = form.get("after", "").strip().replace("-", "/")
        before_date = form.get("before", "").strip().replace("-", "/")
        if not after_date or not before_date:
            raise ValueError("From aur To date dono daalo.")
        query = "(" + query + ") after:" + after_date + " before:" + before_date

    action = form.get("action", "trash")
    if action not in ACTIONS:
        raise ValueError("Invalid action selected.")

    return query, labels, action


def list_gmail_filters(service):
    result = service.users().settings().filters().list(userId="me").execute()
    return result.get("filter", [])


def create_gmail_filter(service, query, action):
    """Create a real, permanent Gmail filter using the native Filters API.

    Gmail filters can prevent mail from reaching the inbox, but they cannot add
    the SPAM system label. For spam-like permanent rules, auto-delete instead.
    """
    body = {
        "criteria": {"query": query},
        "action": {
            "addLabelIds": ["TRASH"],
            "removeLabelIds": ["INBOX", "UNREAD", "IMPORTANT"],
        },
    }
    return service.users().settings().filters().create(userId="me", body=body).execute()


def delete_gmail_filter(service, filter_id):
    service.users().settings().filters().delete(userId="me", id=filter_id).execute()


def fetch_thread_ids(service, query):
    ids = []
    page_token = None

    while True:
        kwargs = {"userId": "me", "q": query, "maxResults": 500}
        if page_token:
            kwargs["pageToken"] = page_token

        result = service.users().threads().list(**kwargs).execute()
        ids.extend([thread["id"] for thread in result.get("threads", [])])

        page_token = result.get("nextPageToken")
        if not page_token:
            return ids


def update_job(job_id, **updates):
    with JOBS_LOCK:
        if job_id in JOBS:
            JOBS[job_id].update(updates)


def get_job(job_id):
    with JOBS_LOCK:
        return dict(JOBS.get(job_id, {}))


def seconds_to_text(seconds):
    seconds = int(max(0, seconds or 0))
    minutes, sec = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)

    if hours:
        return f"{hours}h {minutes}m {sec}s"
    if minutes:
        return f"{minutes}m {sec}s"
    return f"{sec}s"


def process_threads_with_progress(service, ids, job_id, action):
    """Move Gmail threads to Trash OR mark them as Spam, with live progress + safer retry mode.

    Batch size is 10 for maximum safety.
    Failed requests are retried up to 5 times before being counted as failed.
    """
    total = len(ids)
    batch_size = 10
    max_retries = 5
    action_meta = ACTIONS[action]

    update_job(
        job_id,
        total=total,
        status="running",
        message=f"{action_meta['verb']} started... Batch size: {batch_size}, retries: {max_retries}",
    )

    if total == 0:
        update_job(
            job_id,
            status="done",
            percent=100,
            message="No matching emails found.",
            finished_at=time.time(),
        )
        return

    def update_progress_message(extra_message=""):
        job = get_job(job_id)
        done = int(job.get("done", 0))
        failed = int(job.get("failed", 0))
        processed = done + failed
        elapsed = max(0.1, time.time() - float(job.get("started_at", time.time())))
        speed = round(processed / elapsed, 2) if processed else 0
        remaining = max(0, total - processed)
        eta_seconds = int(remaining / speed) if speed > 0 else 0
        percent = round((processed / total) * 100, 1) if total else 100
        filled = min(20, int(percent / 5))

        message = (
            f"[{'█' * filled}{'░' * (20 - filled)}] "
            f"{percent}% | {processed}/{total} | Speed: {speed}/sec | "
            f"ETA: {seconds_to_text(eta_seconds)} | Failed: {failed}"
        )
        if extra_message:
            message += f" | {extra_message}"

        update_job(
            job_id,
            processed=processed,
            percent=percent,
            speed=speed,
            eta=eta_seconds,
            eta_text=seconds_to_text(eta_seconds),
            message=message,
        )

    def trash_chunk(chunk, attempt):
        successful_ids = []
        failed_ids = []

        def callback(request_id, response, exception):
            if exception is None:
                successful_ids.append(request_id)
            else:
                failed_ids.append(request_id)

        batch = BatchHttpRequest(
            callback=callback,
            batch_uri="https://gmail.googleapis.com/batch/gmail/v1",
        )

        for thread_id in chunk:
            if action == "spam":
                request_obj = service.users().threads().modify(
                    userId="me",
                    id=thread_id,
                    body={"addLabelIds": ["SPAM"], "removeLabelIds": ["INBOX", "UNREAD", "IMPORTANT"]},
                )
            else:
                request_obj = service.users().threads().trash(userId="me", id=thread_id)

            batch.add(request_obj, request_id=thread_id)

        try:
            batch.execute()
        except Exception:
            # If the whole batch fails, retry the full chunk.
            failed_ids = list(chunk)
            successful_ids = []

        return successful_ids, failed_ids

    for index in range(0, total, batch_size):
        original_chunk = ids[index:index + batch_size]
        pending = list(original_chunk)

        for attempt in range(1, max_retries + 1):
            if not pending:
                break

            update_progress_message(
                f"Batch {index // batch_size + 1}, attempt {attempt}/{max_retries}"
            )

            successful_ids, failed_ids = trash_chunk(pending, attempt)

            if successful_ids:
                job = get_job(job_id)
                update_job(job_id, done=int(job.get("done", 0)) + len(successful_ids))

            pending = failed_ids

            if pending and attempt < max_retries:
                # Small pause helps Gmail API settle before retry.
                time.sleep(0.8)

        if pending:
            job = get_job(job_id)
            update_job(job_id, failed=int(job.get("failed", 0)) + len(pending))

        update_progress_message()
        time.sleep(0.2)

    job = get_job(job_id)
    done = int(job.get("done", 0))
    failed = int(job.get("failed", 0))
    update_job(
        job_id,
        status="done",
        percent=100,
        eta=0,
        eta_text="0s",
        message=f"Done! {done} threads {action_meta['done_text']}. Failed: {failed}",
        finished_at=time.time(),
    )

def run_process_job(job_id, query, action, credentials_info):
    try:
        update_job(job_id, status="scanning", message="Searching matching Gmail threads...")
        service = gmail_service_from_info(credentials_info)
        ids = fetch_thread_ids(service, query)
        update_job(job_id, total=len(ids), message=f"Found {len(ids)} threads. Starting {ACTIONS[action]['verb'].lower()}...")
        process_threads_with_progress(service, ids, job_id, action)
    except Exception as exc:
        update_job(
            job_id,
            status="error",
            message=str(exc),
            finished_at=time.time(),
        )


