@app.route("/login")
def login():
    flow = Flow.from_client_config(
        client_config(),
        scopes=SCOPES,
        redirect_uri=callback_url(),
    )

    auth_kwargs = {
        "access_type": "offline",
        "include_granted_scopes": "true",
    }
    if request.args.get("force") == "1":
        auth_kwargs["prompt"] = "consent"

    auth_url, state = flow.authorization_url(**auth_kwargs)

    session["state"] = state
    return redirect(auth_url)


@app.route("/callback")
def callback():
    try:
        flow = Flow.from_client_config(
            client_config(),
            scopes=SCOPES,
            state=session.get("state"),
            redirect_uri=callback_url(),
        )

        auth_response = request.url
        if auth_response.startswith("http://") and "onrender.com" in auth_response:
            auth_response = auth_response.replace("http://", "https://", 1)

        flow.fetch_token(authorization_response=auth_response)
        credentials = flow.credentials

        service = build("gmail", "v1", credentials=credentials, cache_discovery=False)
        email = service.users().getProfile(userId="me").execute().get("emailAddress", "").lower()

        allow_list = allowed_emails()
        if allow_list and email not in allow_list:
            session.clear()
            return render_page(
                """
                <div class="box">
                  <h2>Access denied</h2>
                  <p>This email is not allowed to use this app.</p>
                  <a class="btn btn2" href="{{ url_for('home') }}">Back</a>
                </div>
                """,
                msg=email + " ALLOWED_EMAILS me nahi hai.",
            )

        # Google only returns a refresh_token on the very first consent (or when
        # prompt=consent is forced). If it's missing here, the app can't do any
        # background/offline work later (rules, batch clean). Auto-repair once
        # by silently sending the user through a force-consent round trip,
        # instead of storing broken credentials and failing later with a
        # confusing error.
        if not credentials.refresh_token:
            if session.get("_reauth_attempted"):
                session.pop("_reauth_attempted", None)
                return render_page(
                    """
                    <div class="box">
                      <h2>Could not get offline access</h2>
                      <p>Google baar baar refresh_token nahi de raha. Apne Google
                         Account permissions se pehle is app ka access revoke karo,
                         phir dobara login karo.</p>
                      <a class="btn" href="https://myaccount.google.com/permissions" target="_blank">Open Google Permissions</a>
                      <br><br>
                      <a class="btn btn2" href="{{ url_for('home') }}">Back</a>
                    </div>
                    """,
                    msg="Error",
                )
            session["_reauth_attempted"] = True
            return redirect(url_for("login", force=1))

        session.pop("_reauth_attempted", None)
        session["credentials"] = credentials_to_dict(credentials)
        session["email"] = email
        return redirect(url_for("dashboard"))

    except Exception as exc:
        return render_page(
            """
            <div class="box">
              <h2>OAuth Error</h2>
              <p>Google login complete nahi hua.</p>
              <code>{{ error }}</code>
              <br>
              <a class="btn btn2" href="{{ url_for('home') }}">Try again</a>
            </div>
            """,
            error=str(exc),
            msg="Login failed",
        )


